    private fun line(name: String, d: String, mirror: Boolean = false) = build(name, d, mirror, fill = false, stroke = true)
    private fun filled(name: String, d: String, mirror: Boolean = false) = build(name, d, mirror, fill = true, stroke = true)
    private fun solid(name: String, d: String, mirror: Boolean = false) = build(name, d, mirror, fill = true, stroke = false)

    private fun build(name: String, d: String, mirror: Boolean, fill: Boolean, stroke: Boolean): ImageVector =
        ImageVector.Builder(
            name = "BtIcons.$name",
            defaultWidth = 24.dp,
            defaultHeight = 24.dp,
            viewportWidth = 24f,
            viewportHeight = 24f,
            autoMirror = mirror,
        ).addPath(
            pathData = addPathNodes(d),
            pathFillType = if (stroke) PathFillType.NonZero else PathFillType.EvenOdd,
            fill = if (fill) SolidColor(Color.Black) else null,
            stroke = if (stroke) SolidColor(Color.Black) else null,
            strokeLineWidth = STROKE,
            strokeLineCap = StrokeCap.Round,
            strokeLineJoin = StrokeJoin.Round,
        ).build()
}
